//! Usage: servo-openapi > web/openapi.json
//!
//! Prints the deterministic pretty-printed OpenAPI 3.1 document from
//! `servo_ident::openapi::document()` to stdout. The committed
//! `web/openapi.json` is regenerated by piping this into that file; a
//! contract test fails when the two drift.

fn main() {
    let doc = servo_ident::openapi::document();
    let mut text = serde_json::to_string_pretty(&doc).expect("openapi document always serializes");
    text.push('\n');
    print!("{text}");
}
